using Xunit;

public class MachineLearningTests
{
    [Fact]
    public void TestTrainingDataInitialLoad()
    {
        // Arrange
        var machineLearningSystem = new MachineLearningSystem();
        var trainingData = new TrainingData();

        // Act
        machineLearningSystem.Train(trainingData);

        // Assert
        Assert.True(machineLearningSystem.IsTrained);
    }

    [Fact]
    public void TestTrainingDataCombination()
    {
        // Arrange
        var machineLearningSystem = new MachineLearningSystem();
        var initialTrainingData = new TrainingData();
        var liveData = new LiveData();

        // Act
        machineLearningSystem.Train(initialTrainingData);
        machineLearningSystem.CombineData(liveData);

        // Assert
        Assert.True(machineLearningSystem.IsTrained);
        Assert.True(machineLearningSystem.IsDataCombined);
    }

    [Fact]
    public void TestPredictionAccuracyAfterOneYear()
    {
        // Arrange
        var machineLearningSystem = new MachineLearningSystem();
        var trainingData = new TrainingData();
        machineLearningSystem.Train(trainingData);

        // Act
        var predictionAccuracy = machineLearningSystem.GetPredictionAccuracy();

        // Assert
        Assert.InRange(predictionAccuracy, 50, 60);
    }

    [Fact]
    public void TestSeasonalDiseasePrediction()
    {
        // Arrange
        var machineLearningSystem = new MachineLearningSystem();
        var trainingData = new TrainingData();
        machineLearningSystem.Train(trainingData);

        // Act
        var seasonalPrediction = machineLearningSystem.PredictSeasonalDisease();

        // Assert
        Assert.NotNull(seasonalPrediction);
    }

    [Fact]
    public void TestDiseaseOutbreakPrediction()
    {
        // Arrange
        var machineLearningSystem = new MachineLearningSystem();
        var trainingData = new TrainingData();
        machineLearningSystem.Train(trainingData);

        // Act
        var outbreakPrediction = machineLearningSystem.PredictDiseaseOutbreak();

        // Assert
        Assert.NotNull(outbreakPrediction);
    }

    [Fact]
    public void TestPaymentGatewayInterface()
    {
        // Arrange
        var paymentGateway = new PaymentGateway();
        var paymentDetails = new PaymentDetails();

        // Act
        paymentGateway.ProcessPayment(paymentDetails);

        // Assert
        Assert.True(paymentGateway.IsPaymentProcessed);
    }

    [Fact]
    public void TestCashPaymentMode()
    {
        // Arrange
        var paymentGateway = new PaymentGateway();
        var paymentDetails = new PaymentDetails { PaymentMethod = "Cash" };

        // Act
        paymentGateway.ProcessPayment(paymentDetails);

        // Assert
        Assert.True(paymentGateway.IsPaymentProcessed);
    }
}
